class Solution {
public:
    int reachNumber(int target) {
        long long t = target < 0 ? -(long long)target : (long long)target;
        long long lo = 0, hi = 1;
        while (hi * (hi + 1) / 2 < t) hi *= 2;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (mid * (mid + 1) / 2 >= t) hi = mid;
            else lo = mid + 1;
        }
        long long k = lo;
        long long s = k * (k + 1) / 2;
        while (((s - t) & 1LL) != 0) {
            k++;
            s += k;
        }
        return (int)k;
    }
};
